import * as Token from 'token-types';
import { StringType } from 'token-types';
import * as util from '../common/Util.js';
export const PageHeader = {
    len: 27,
    get: (buf, off) => {
        const granulePosition = Token.UINT64_LE.get(buf, off + 6);
        return {
            capturePattern: new StringType(4, 'latin1').get(buf, off),
            version: Token.UINT8.get(buf, off + 4),
            headerType: {
                continued: util.getBit(buf, off + 5, 0),
                firstPage: util.getBit(buf, off + 5, 1),
                lastPage: util.getBit(buf, off + 5, 2)
            },
            // packet_flag: Token.UINT8.get(buf, off + 5),
            absoluteGranulePosition: granulePosition === 0xffffffffffffffffn ? -1 : Number(granulePosition),
            streamSerialNumber: Token.UINT32_LE.get(buf, off + 14),
            pageSequenceNo: Token.UINT32_LE.get(buf, off + 18),
            pageChecksum: Token.UINT32_LE.get(buf, off + 22),
            page_segments: Token.UINT8.get(buf, off + 26)
        };
    }
};
export class SegmentTable {
    len;
    constructor(header) {
        this.len = header.page_segments;
    }
    get(buf, off) {
        const lacingValues = Uint8Array.from(buf.subarray(off, off + this.len));
        return {
            totalPageSize: lacingValues.reduce((sum, length) => sum + length, 0),
            lacingValues
        };
    }
}
